  multiAccess.multiAccessIsOwner(address, function(err, isOwner) {
    if (err) {
      logError(err, $logs);
      return;
    }
    if (!isOwner) {
      logError(address + ' is not an owner of multi access at address: ' + multiAccess.address + '.');
      logError('Permission denied.', $logs);
      return;
    }
    log('MultiAccess ownership - PASSED.', $logs);
    multiAccess.multiAccessRequired(function(err, required) {
      if (err) {
        logError(err, $logs);
        return;
      }
      if (required.gt(1)) {
        logError('Multi access at address: ' + multiAccess.address + ' require ' + required.valueOf() + ' confirmations, which is more than 1 that should be set for successful setup.');
        logError('Not enough permissions.', $logs);
        return;
      }
      log('MultiAccess requirements - PASSED.', $logs);
      web3.eth.getBalance(address, 'pending', function(err, etherBalance) {
        if (err) {
          logError(err, $logs);
          return;
        }
        if (etherBalance.lte(etherToDeposit)) {
          logError('Your current balance is ' + web3.fromWei(etherBalance, 'ether').valueOf() + ' ETH. While it should be more than ' + etherToDeposit + ' ETH. Please topup and try again.');
          logError('Insufficient ether balance.', $logs);
          return;
        }
        log('Ether balance - PASSED.', $logs);
        if (refunderSaas) {
          ambiProd.hasRelation(refunderSaasNodeName, 'admin', refunderSaasAdminAddress, function(err, result) {
            if (err) {
              logError(err, $logs);
              return;
            }
            if (!result) {
              logError(refunderSaasAdminAddress + ' doesn\'nt have an admin role on SaaS refunder with name: ' + refunderSaasNodeName + '. Please do safeTransaction(ambi.setRelation, ["' + refunderSaasNodeName + '", "admin", "commonAmbi"], address);');
              logError('Permission denied.', $logs);
              return;
            }
            log('SaaS refunder admin role - PASSED.', $logs);
            action();
          });
        } else {
          if (refunderAddress) {
            ambi.isRelation(treasuryNodeName, 'admin', myNodeName, function(err, result) {
              if (err) {
                logError(err, $logs);
                return;
              }
              if (!result) {
                logError(myNodeName + ' doesn\'nt have an admin role on refunder at address: ' + refunderAddress + '. Please do safeTransaction(ambi.setRelation, ["' + treasuryNodeName + '", "admin", "' + myNodeName + '"], address);');
                logError('Permission denied.', $logs);
                return;
              }
              log('Refunder admin role - PASSED.', $logs);
              action();
            });
          } else {
            action();
          }
        }
      });
    });
  });
